// and escalate the owner once per head (label + 🛑 comment). A lap that
// pushed OR resolved anything, or a new head, resets the count by
// construction (the lap markers are head-keyed).
function noopLapMaxOf(jobParams) {
    var n = (jobParams || {}).noopLapMax;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    return (typeof n === 'number' && n > 0) ? Math.floor(n) : reworkLoopGuardModule.DEFAULT_NOOP_LAP_MAX;
}

// Invalidate-after-mutation (owner directive 2026-10-04): PR labels changed
// mid-tick — a later rule re-querying the open-PR list in the SAME tick
// (validate-armed's mutex) must see it. Guarded: harnesses may stub the
// provider module down to createSmProvider alone.
function dropOpenPrsCache(repoInfo) {
    try {
        if (smProviderModule && typeof smProviderModule.ioCacheDrop === 'function') {
            smProviderModule.ioCacheDrop(
                repoInfo.owner, repoInfo.repo, 'openPrs', null);
        }
    } catch (eDrop) { /* stale cache costs one extra tick, never a wrong arm */ }
}

// gh-862: the merge-validated probe — the squash-merge attempt shared by
// the merge_pr action, the latch-skip arm-only path and the gh-857
// conclude-success path. Live fa #1457 (rel-20261011-204928, two ticks
// 21:01Z/21:06Z): the latch-skip armed ai_validating WITHOUT a dispatch
// and continued — but merge-validated runs EARLIER in the deployed rule
// order (sm_github.json index 6 vs validate-armed 11), so the arm landed
// after the merge window had already closed; the sweep ate the arm next
// tick ('stale arm swept') and the latch-skip re-armed — arm → sweep →
// re-arm ping-pong, the conclude and the merge unreachable for exactly
// the PRs that need them. Every ai_validated + green PR must get the
// probe (placeholder conclude first, then the merge attempt) in the tick
// that arms/concludes it.
// Returns 'merged' | 'latched' (an un-approved green head: ai_validating
// unarmed + ai_validated latched, review follows — review-after-dev
// requires ai_validated). THROWS on a refused merge (anything but an
// explicit merged:true — fa pr-753 parity: the HTTP layer returns the
// raw body for error statuses, a 405 "not mergeable" arrives as
// {"merged": false, ...} with NO thrown error; the markers MUST stay so
// the loop self-heals: unarm-stale → refresh → re-validate → retry).
}

// ── gh-1101 follow-up: fresh-sha reset guard ─────────────────────────────
var tickFreshResets = {};

function prHeadShaSafe(repoInfo, prNumber) {
    try {
        var pr = mcpParse(github_get_pr({ workspace: repoInfo.owner,
            repository: repoInfo.repo, pullRequestId: prNumber })) || {};
        return (pr.head && (pr.head.sha || pr.head)) || null;
    } catch (e) {
        return null;
    }
}

function headMoved(oldHead, newHead) {
    return typeof newHead === 'string' && !!newHead && newHead !== oldHead;
}

// One reset per PR per tick; runs `refresh`, then verifies the PR head
// actually moved off oldHead. true = moved (caller counts + marks).
function freshShaResetOnce(repoInfo, ticket, key, oldHead, refresh) {
    if (tickFreshResets[ticket.prNumber]) {
        console.log('  ⏭️  ' + key + ' fresh-sha reset already done this tick — skip');
        return false;
    }
    tickFreshResets[ticket.prNumber] = true;
    try {
        refresh();
    } catch (eUp) {
        console.warn('  ⚠️  ' + key + ' fresh-sha refresh failed: ' + (eUp.message || eUp) +
    } catch (eRhs) {
        console.warn('  ⚠️  head sha resolve failed for ' +
            (ticket.key || ('pr-' + ticket.prNumber)) + ': ' + (eRhs.message || eRhs));
        return null;
    }
}

// gh-846: FRESH PR head read for the post-refresh stale-cancel. Deliberately
// bypasses the ticket's cached headSha: the silent refresh just moved the
// head, so any cached sha is the PRE-refresh one — cancelling against it
// would select runs on the CURRENT head (AC4: never touch those). One
// github_get_pr per refreshed PR. Fail CLOSED (null): without the true new
// head the stale selection cannot run safely — the dead-head runs wait one
// tick; a wrongful cancel is the worse failure.
function freshHeadSha(repoInfo, prNumber) {
