    // NO failure marker, NO silent-update-degraded label.
    parkNonEditableFork();
    console.log('  🅿️  ' + key + ' fork head is not maintainer-editable — ' +
        'guest park, zero silent-update attempts (gh-1070 AC2)');
    return { refresh: false, forkFull: forkFull };
