        assert.equal(sm.capturedPrComments.length, 0, 'no park comment on a moved head (I5)');
        assert.equal(sm.capturedPrLabelRemoves.filter(function (l) {
            return l.label === 'ai_validating'; }).length, 0, 'the fail path never ran');
    });

