        assert.equal(sm.capturedPrMerges.length, 1, 'the unmoved candidate (pr-71) merges in the same tick');
        assert.equal(sm.capturedPrMerges[0].pullRequestId, 71, 'the merge is pr-71, not the deferred pr-70');
    });

