function createTargetScm(effectiveConfig, repoInfo) {
    if (!repoInfo || !repoInfo.owner || !repoInfo.repo) {
        return scmModule.createScm(effectiveConfig);
    }
    var cfg = {};
    if (effectiveConfig) {
        for (var k in effectiveConfig) {
